package com.dronefleet.security;
import java.security.*;import java.util.Base64;import javax.crypto.SecretKeyFactory;import javax.crypto.spec.PBEKeySpec;
public final class PasswordHasher{private static final int ITER=120000,SALT=16,KEY=256;public static String hash(String password){try{byte[] salt=new byte[SALT];SecureRandom.getInstanceStrong().nextBytes(salt);byte[] key=derive(password,salt,ITER);return ITER+":"+Base64.getEncoder().encodeToString(salt)+":"+Base64.getEncoder().encodeToString(key);}catch(Exception e){throw new IllegalStateException(e);}}public static boolean verify(String password,String encoded){try{String[] x=encoded.split(":");int it=Integer.parseInt(x[0]);byte[] salt=Base64.getDecoder().decode(x[1]);byte[] expected=Base64.getDecoder().decode(x[2]);return MessageDigest.isEqual(expected,derive(password,salt,it));}catch(Exception e){return false;}}private static byte[] derive(String p,byte[] s,int it)throws Exception{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new PBEKeySpec(p.toCharArray(),s,it,KEY)).getEncoded();}}
